options.customCss:
/* Profit Leak Analyzer — Upload Form Theme */

:root {
  --pla-navy: #14283f;
  --pla-teal: #087f62;
  --pla-bg: #f3f6fb;
  --pla-text: #263b53;
  --pla-muted: #64748b;
  --pla-border: #dfe6ef;
}

/* Page */
body {
  background: var(--pla-bg) !important;
  color: var(--pla-text);
  font-family: Inter, system-ui, -apple-system,
    "Segoe UI", Arial, sans-serif !important;
  line-height: 1.6;
}

/* Main form panel */
form {
  background: #ffffff;
  border: 1px solid var(--pla-border);
  border-radius: 18px;
  padding: 28px;
  box-shadow: 0 12px 36px rgba(20, 40, 63, 0.06);
}

/* Headings */
h1, h2, h3 {
  color: var(--pla-navy);
  font-weight: 750;
  letter-spacing: -0.4px;
}

h1 {
  font-size: clamp(25px, 3vw, 32px);
}

/* Supporting text */
p {
  color: var(--pla-muted);
  line-height: 1.7;
}

label {
  color: var(--pla-text);
  font-weight: 600;
  font-size: 13px;
}

/* Form controls */
input:not([type="checkbox"]),
textarea,
select {
  background: #ffffff;
  color: var(--pla-text);
  border: 1px solid #cbd5e1;
  border-radius: 9px;
  padding: 12px 14px;
  font-family: inherit;
  font-size: 14px;
  transition: border-color 0.2s,
    box-shadow 0.2s;
}

input:focus,
textarea:focus,
select:focus {
  outline: 2px solid transparent;
  border-color: var(--pla-teal);
  box-shadow: 0 0 0 3px
    rgba(8, 127, 98, 0.13);
}

/* File upload controls */
input[type="file"] {
  border: 1px dashed #b7c7d7;
  background: #f8fafc;
  border-radius: 10px;
  padding: 16px;
  width: 100%;
}

input[type="file"]::file-selector-button {
  background: #e8f3ee;
  color: #086c50;
  border: 0;
  border-radius: 7px;
  padding: 9px 13px;
  margin-right: 12px;
  font-weight: 650;
  cursor: pointer;
}

/* Confirmation checkbox */
input[type="checkbox"] {
  accent-color: var(--pla-teal);
  width: 17px;
  height: 17px;
}

/* Primary submit action */
button[type="submit"] {
  background: var(--pla-navy) !important;
  color: #ffffff !important;
  border: 0;
  border-radius: 10px;
  padding: 15px 24px;
  font-weight: 700;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.2s,
    transform 0.2s;
}

button[type="submit"]:hover {
  background: #244867 !important;
  transform: translateY(-1px);
}

button[type="submit"]:focus-visible {
  outline: 3px solid #087f62;
  outline-offset: 3px;
}

/* Links */
a {
  color: var(--pla-teal);
  font-weight: 600;
}

a:hover {
  color: #075b49;
}

/* Mobile */
@media (max-width: 640px) {
  body {
    padding: 12px;
  }

  form {
    padding: 20px 16px;
    border-radius: 14px;
  }

  input[type="file"] {
    padding: 12px;
  }

  button[type="submit"] {
    width: 100%;
  }
}

