    if (!h || !f || f === 'UNMAPPED') return;
    if (headers.indexOf(h) < 0) { rejected.push({ header: h, canonical_field: f, reason: 'header_not_in_file' }); return; }
    if (!Object.prototype.hasOwnProperty.call(fields, f)) { rejected.push({ header: h, canonical_field: f, reason: 'unknown_canonical_field' }); return; }
    if (taken[f]) { rejected.push({ header: h, canonical_field: f, reason: 'field_already_mapped' }); return; }
    if (usedHeaders[h]) { rejected.push({ header: h, canonical_field: f, reason: 'header_already_mapped' }); return; }
