// ---- Parse & fingerprint uploaded CSV files ----
const MAX_BYTES = 2 * 1024 * 1024;
const MAX_ROWS = 5000;
const item = $input.first();
const form = item.json || {};
const binary = item.binary || {};
const importErrors = [];
const notes = [];

function fail(source, code, message) { importErrors.push({ source: source, code: code, message: message }); }

// Strict RFC 4180 parser. Returns {rows} or {error}. Values are kept as exact strings.
function parseCsv(text) {
  const rows = []; let row = []; let field = ''; let i = 0; let inQuotes = false; let fieldQuoted = false; let line = 1;
  const n = text.length;
  while (i < n) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++;
        const nx = text[i];
        if (i < n && nx !== ',' && nx !== '\n' && nx !== '\r') return { error: 'Unexpected character after closing quote on line ' + line };
        continue;
      }
      if (ch === '\n') line++;
      field += ch; i++; continue;
    }
    if (ch === '"') {
      if (field !== '' || fieldQuoted) return { error: 'Quote inside unquoted field on line ' + line };
      inQuotes = true; fieldQuoted = true; i++; continue;
    }
    if (ch === ',') { row.push(field); field = ''; fieldQuoted = false; i++; continue; }
    if (ch === '\r' || ch === '\n') {
      row.push(field); rows.push({ cells: row, line: line }); row = []; field = ''; fieldQuoted = false;
      if (ch === '\r' && text[i + 1] === '\n') i++;
      i++; line++; continue;
    }
    field += ch; i++;
  }
  if (inQuotes) return { error: 'Unterminated quoted field starting before end of file' };
