}

function findBinaryKey(field) {
  const keys = Object.keys(binary);
  if (keys.indexOf(field) >= 0) return field;
  const pref = keys.filter(function (k) { return k.indexOf(field) === 0; }).sort();
  return pref.length ? pref[0] : null;
}

const sellerRaw = String(form.seller_id || '').trim();
if (!/^[A-Za-z0-9_-]{1,40}$/.test(sellerRaw)) fail('form', 'INVALID_SELLER_ID', 'Seller ID must be 1-40 letters, digits, - or _');
const seller = sellerRaw.toUpperCase();
const asOf = String(form.as_of_date || '').trim().slice(0, 10);
