check('pla_results', rowsOf('Read Back Results'), (E.results || []).length);
check('pla_exceptions', rowsOf('Read Back Exceptions'), (E.exceptions || []).length, 'exception_id', (E.exceptions || []).map(function (x) { return x.exception_id; }));
check('pla_validation_errors', rowsOf('Read Back Validation Errors'), (E.validation_errors || []).length);
check('pla_settlement_summary', rowsOf('Read Back Settlements'), (E.settlement_summary || []).length, 'settlement_id', (E.settlement_summary || []).map(function (s) { return s.settlement_id; }));

function canonicalJson(value) {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    return '[' + value.map(canonicalJson).join(',') + ']';
  }

  return '{' + Object.keys(value).sort().map(function (key) {
    return JSON.stringify(key) + ':' +
      canonicalJson(value[key]);
