  const stored = rowsOf(nodeName);
  const failures = [];
  const bySeq = new Map();

  for (const row of stored) {
    const seq = Number(row.seq);

    if (!Number.isSafeInteger(seq) || bySeq.has(seq)) {
      failures.push('Invalid or duplicate sequence: ' + row.seq);
      continue;
    }

    bySeq.set(seq, row);
  }

  expectedRows.forEach(function (expected, seq) {
    const row = bySeq.get(seq);

    if (!row) {
      failures.push('Missing sequence: ' + seq);
      return;
    }

    try {
      const actual = JSON.parse(row[jsonField]);

      if (canonicalJson(actual) !== canonicalJson(expected)) {
        failures.push('Content mismatch at sequence: ' + seq);
